package org.demo.orderservice.privacy;

import org.demo.platformsecurity.privacy.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;
import static org.demo.platformsecurity.privacy.CommerceRetentionAssessment.*;
import static org.demo.orderservice.privacy.CommerceRetentionHoldRestorationPreparation.*;
import org.demo.orderservice.privacy.CommerceRetentionHoldRestorationReview.Code;
import static org.demo.orderservice.privacy.CommerceRetentionHoldRestorationReview.*;
import static org.demo.orderservice.privacy.CommerceRetentionHoldRestorationProgress.*;

import org.demo.orderservice.privacy.CommerceRetentionHoldRepairAssessment.State;
import java.time.Instant;

@Testcontainers
class CommerceRetentionHoldRestorationReviewPostgresIT {
    @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("hold_restoration_preparation").withUsername("fixture").withPassword("fixture-only");
    static DriverManagerDataSource ds;static JdbcTemplate jdbc;static DataSourceTransactionManager manager;
    CommerceRetentionHoldRestorationPreparation preparation;CommerceRetentionHoldRecoveryPlanning planning;CommerceRetentionHoldRepairAssessment assessment;CommerceRetentionHoldReconciliationHistory history;CommerceRetentionHoldDelivery sender;CommerceRetentionHoldIntake.Registration intake;
    @BeforeAll static void initialize(){ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();}
    @BeforeEach void reset(){
        jdbc.execute("TRUNCATE orders,commerce_retention_holds,commerce_retention_hold_scopes RESTART IDENTITY CASCADE");
        jdbc.update("INSERT INTO orders(id,customer_id,customer_email,total_price,status,delivery_first_name,delivery_last_name,delivery_street,delivery_postal_code,delivery_city,delivery_country,delivery_phone,delivery_method,delivery_cost,discount_amount,fulfillment_type,idempotency_key,checkout_request_hash,checkout_principal,created_at,updated_at) VALUES(10,17,'fixture@example.test',10,'CANCELLED','Fixture','Buyer','Street','00-001','City','PL','123','COURIER',0,0,'HOME_DELIVERY','fixture-10',?,'fixture',now(),now())","a".repeat(64));
        intake=new CommerceRetentionHoldIntake(ds,manager).register(10,UUID.randomUUID(),UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,CommerceRetentionHolds.Reason.PRESERVATION_REQUEST);
        preparation=new CommerceRetentionHoldRestorationPreparation(ds,manager);planning=new CommerceRetentionHoldRecoveryPlanning(ds,manager);assessment=new CommerceRetentionHoldRepairAssessment(ds,manager);history=new CommerceRetentionHoldReconciliationHistory(ds,manager);sender=new CommerceRetentionHoldDelivery(ds,manager);
        for(var p:CommerceRetentionSourceHolds.SOURCES)sender.deliver(10,intake.requestId(),intake.caseReference(),p,c->new SourceHoldDeliveryProtocol.Reply(c,SourceHoldDeliveryProtocol.Code.RECORDED,UUID.randomUUID()));
    }
    UUID put(Participant p,CommerceRetentionHoldReconciliation.Code code,Instant time){
        int n=jdbc.queryForObject("SELECT count(*)+1 FROM commerce_retention_hold_probes WHERE request_id=? AND source=?",Integer.class,intake.requestId(),p.name());UUID probe=UUID.randomUUID();
        jdbc.update("INSERT INTO commerce_retention_hold_probes(request_id,source,probe_no,probe_id,source_request_id,source_hold_id) SELECT request_id,source,?,?,source_request_id,source_hold_id FROM commerce_retention_hold_delivery_receipts WHERE request_id=? AND source=?",n,probe,intake.requestId(),p.name());
        if(code!=null){boolean observed=Set.of(CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,CommerceRetentionHoldReconciliation.Code.MISSING_AT_SOURCE,CommerceRetentionHoldReconciliation.Code.SOURCE_CONFLICT,CommerceRetentionHoldReconciliation.Code.SOURCE_UNKNOWN,CommerceRetentionHoldReconciliation.Code.SOURCE_QUARANTINED).contains(code);boolean versioned=observed && code!=CommerceRetentionHoldReconciliation.Code.SOURCE_UNKNOWN;
            jdbc.update("INSERT INTO commerce_retention_hold_probe_results(probe_id,code,observed_at,binding_epoch,source_revision) VALUES(?,?,?,?,?)",probe,code.name(),observed?java.sql.Timestamp.from(time):null,versioned?2:0,versioned?3:0);
        }return probe;
    }
    UUID intent(Participant source){put(source,CommerceRetentionHoldReconciliation.Code.MISSING_AT_SOURCE,Instant.now());UUID id=UUID.randomUUID();assertThat(planning.prepare(10,intake.requestId(),intake.caseReference(),source,id).code()).isEqualTo(CommerceRetentionHoldRecoveryPlanning.Code.PREPARED);return id;}
    Prepared prepare(Participant source,UUID intent,SourceHoldRestorationProtocol.Mode mode){return preparation.prepare(10,intake.requestId(),intake.caseReference(),source,intent,UUID.randomUUID(),"fixture-sensitive-authorization",mode);}

    CommerceRetentionHoldRestorationDispatch dispatch(){return new CommerceRetentionHoldRestorationDispatch(ds,manager,RestorationCaseFixture.verifier());}
    SourceHoldRestorationProtocol.Command command(Participant p,UUID id){return RestorationCaseFixture.authorize(preparation.prepare(10,intake.requestId(),intake.caseReference(),p,id,UUID.randomUUID(),"",SourceHoldRestorationProtocol.Mode.RESTORE).command());}
    CommerceRetentionHoldRestorationDispatch.Result step(SourceHoldRestorationProtocol.Command c,CommerceRetentionHoldRestorationDispatch.Transport remote){return dispatch().step(10,intake.requestId(),intake.caseReference(),c.delivery().source(),c.intentId(),c.challenge(),c.mode(),c.authorization(),remote);}
    SourceHoldRestorationProtocol.Reply success(SourceHoldRestorationProtocol.Command c){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return SourceHoldRestorationProtocol.reply(c,c.mode()==SourceHoldRestorationProtocol.Mode.RESTORE?SourceHoldRestorationProtocol.Code.RESTORED:SourceHoldRestorationProtocol.Code.REPLAYED,c.bindingEpoch(),c.sourceRevision()+1,RestorationCaseFixture.verifier().verify(c).id());}


    static void awaitReviewClock(UUID intent){
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);
        while(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT clock_timestamp()>GREATEST(i.created_at,COALESCE((SELECT max(created_at) FROM commerce_retention_hold_restoration_attempts WHERE intent_id=i.intent_id),'epoch'::timestamptz),COALESCE((SELECT max(r.recorded_at) FROM commerce_retention_hold_restoration_results r JOIN commerce_retention_hold_restoration_attempts a USING(attempt_id) WHERE a.intent_id=i.intent_id),'epoch'::timestamptz))+interval '20 milliseconds' FROM commerce_retention_hold_repair_intents i WHERE i.intent_id=?",Boolean.class,intent))){
            assertThat(System.nanoTime()).as("Fixture database clock must pass prior repair metadata").isLessThan(deadline);
            try{Thread.sleep(2);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new AssertionError(interrupted);}
        }
    }
    CommerceRetentionHoldRestorationProgress progress(){return new CommerceRetentionHoldRestorationProgress(ds,manager);}
    Progress assess(UUID id){return progress().assess(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,id);}
    Refresh refresh(Participant source,UUID id,UUID probe,CommerceRetentionHoldReconciliation.Transport remote){awaitReviewClock(id);return progress().refresh(10,intake.requestId(),intake.caseReference(),source,id,probe,remote);}
    SourceHoldInspectionProtocol.Reply match(SourceHoldInspectionProtocol.Command c){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new SourceHoldInspectionProtocol.Reply(c,SourceHoldInspectionProtocol.Code.MATCH,Instant.now(),2,4);}
    UUID acknowledged(Participant source){UUID id=intent(source);assertThat(step(command(source,id),this::success).outcome()).isEqualTo("RESTORED");return id;}

    CommerceRetentionHoldRestorationReview aggregate(){return new CommerceRetentionHoldRestorationReview(ds,manager);}
    Review review(){return aggregate().review(10,intake.requestId(),intake.caseReference());}
    Source source(Review r,Participant p){return r.sources().stream().filter(s->s.source()==p).findFirst().orElseThrow();}
    UUID matched(Participant p){UUID id=acknowledged(p);refresh(p,id,UUID.randomUUID(),this::match);return id;}
    @Test void sevenMatchedSourcesRemainLocalDiagnosticsWithoutClearance(){
        for(var p:CommerceRetentionSourceHolds.SOURCES)matched(p);var r=review();assertThat(r.code()).isEqualTo(Code.REVIEWED);assertThat(r.sources()).hasSize(7);assertThat(r.totals().sourcesWithFreshMatches()).isEqualTo(7);assertThat(r.totals().reviewSources()).isZero();assertThat(r.totals().intents()).isEqualTo(7);assertThat(r.totals().attempts()).isEqualTo(7);assertThat(r.totals().historicalAcknowledgements()).isEqualTo(7);assertThat(r.totals().probes()).isEqualTo(14);assertThat(r.localSnapshot()).isTrue();assertThat(r.distributedSnapshot()).isFalse();assertThat(r.currentAuthority()).isFalse();assertThat(r.completeCaseCoverage()).isFalse();assertThat(r.repairExecutionAllowed()).isFalse();assertThat(r.executionTerminated()).isFalse();assertThat(r.activationAllowed()).isFalse();assertThat(r.reviewedAt()).isNotNull();assertThatThrownBy(()->r.sources().clear()).isInstanceOf(UnsupportedOperationException.class);assertThatThrownBy(()->r.sources().getFirst().reasons().add(Reason.UNKNOWN_WRITE)).isInstanceOf(UnsupportedOperationException.class);assertThatThrownBy(()->r.sources().getFirst().intents().clear()).isInstanceOf(UnsupportedOperationException.class);
    }
    @Test void missingIntentIsExplicitForEverySourceWithoutGuessingRepairUnnecessary(){var r=review();assertThat(r.sources()).hasSize(7);assertThat(r.totals().intents()).isZero();assertThat(r.totals().reviewSources()).isEqualTo(7);for(var s:r.sources())assertThat(s.reasons()).containsExactly(Reason.NO_REPAIR_INTENT);}
    @Test void missingReceiptKeepsSourcePlanWithoutInventingHold(){jdbc.execute("TRUNCATE commerce_retention_hold_delivery_receipts CASCADE");var r=review();assertThat(r.sources()).hasSize(7);for(var s:r.sources()){assertThat(s.sourceRequestId()).isNotNull();assertThat(s.sourceHoldId()).isNull();assertThat(s.reasons()).contains(Reason.NO_HISTORICAL_RECEIPT,Reason.NO_REPAIR_INTENT);}assertThat(r.totals().historicalAcknowledgements()).isZero();}
    @Test void allFiftySixIntentsAreKeptAndSharedProbeCountsAreNotMultiplied(){for(var p:CommerceRetentionSourceHolds.SOURCES)for(int n=0;n<8;n++)intent(p);var r=review();assertThat(r.code()).isEqualTo(Code.REVIEWED);assertThat(r.totals().intents()).isEqualTo(56);assertThat(r.totals().probes()).isEqualTo(56);for(var s:r.sources()){assertThat(s.intents()).hasSize(8);assertThat(s.probesUsed()).isEqualTo(8);assertThat(s.remainingProbes()).isZero();assertThat(s.reasons()).contains(Reason.PROBE_BUDGET_EXHAUSTED,Reason.NOT_ATTEMPTED);assertThat(s.intents()).extracting(Intent::basisProbeNumber).containsExactly(1,2,3,4,5,6,7,8);}}
    @Test void pendingAndSupersededProbesAreCountedOnceAcrossMultipleIntents(){intent(Participant.PAYMENT);intent(Participant.PAYMENT);UUID pending=put(Participant.PAYMENT,null,null),replacement=put(Participant.PAYMENT,CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,Instant.now());planning.supersede(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,pending,replacement,UUID.randomUUID());put(Participant.PAYMENT,null,null);var r=review();assertThat(r.totals().intents()).isEqualTo(2);assertThat(r.totals().probes()).isEqualTo(5);assertThat(r.totals().pendingReads()).isEqualTo(1);assertThat(r.totals().supersededReads()).isEqualTo(1);assertThat(source(r,Participant.PAYMENT).reasons()).contains(Reason.READ_PENDING,Reason.SUPERSEDED_READ,Reason.INSPECTION_PENDING);}
    @Test void oldStoppedIntentIsNotHiddenByNewerSuccessfulRepair(){UUID first=matched(Participant.PAYMENT);dispatch().stop(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,first,UUID.randomUUID());UUID second=matched(Participant.PAYMENT);var r=review();var s=source(r,Participant.PAYMENT);assertThat(s.intents()).extracting(Intent::intentId).containsExactly(first,second);assertThat(s.intents().getFirst().stopped()).isTrue();assertThat(s.intents().getLast().progress().inspection()).isEqualTo(Inspection.MATCH_AS_OF_READ);assertThat(s.reasons()).contains(Reason.STOPPED);assertThat(r.totals().stoppedIntents()).isEqualTo(1);assertThat(r.totals().sourcesWithFreshMatches()).isZero();}
    @Test void matchAndLaterReplayDoNotHideUnknownWriteCount(){UUID id=intent(Participant.PAYMENT);var c=command(Participant.PAYMENT,id);step(c,x->{throw new IllegalStateException();});step(RestorationCaseFixture.retry(c,SourceHoldRestorationProtocol.Mode.REPLAY_ONLY),this::success);refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match);var r=review();assertThat(r.totals().attempts()).isEqualTo(2);assertThat(r.totals().historicalAcknowledgements()).isEqualTo(1);assertThat(r.totals().pendingWrites()).isEqualTo(1);assertThat(r.totals().sourcesWithFreshMatches()).isEqualTo(1);assertThat(source(r,Participant.PAYMENT).reasons()).contains(Reason.UNKNOWN_WRITE);}
    @ParameterizedTest @ValueSource(strings={"order","request","case"})
    void unknownScopeReturnsNoPartialRowsOrCounters(String change){matched(Participant.PAYMENT);var r=aggregate().review(change.equals("order")?11:10,change.equals("request")?UUID.randomUUID():intake.requestId(),change.equals("case")?UUID.randomUUID():intake.caseReference());assertThat(r.code()).isEqualTo(Code.UNKNOWN_REQUEST);assertThat(r.sources()).isEmpty();assertThat(r.totals().sources()).isZero();assertThat(r.localSnapshot()).isFalse();}
    @ParameterizedTest @ValueSource(strings={"parent","order-scope","customer-scope","order-state"})
    void quarantinePreservesAllSevenSourcesAndStopCounters(String change){UUID id=matched(Participant.PAYMENT);dispatch().stop(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,id,UUID.randomUUID());switch(change){case "parent"->jdbc.update("UPDATE commerce_retention_hold_requests SET restore_blocked=TRUE");case "order-scope"->jdbc.update("UPDATE commerce_retention_hold_scopes SET restore_blocked=TRUE");case "customer-scope"->jdbc.update("INSERT INTO commerce_retention_hold_scopes(scope_type,subject_id,restore_blocked) VALUES('CUSTOMER',17,TRUE)");case "order-state"->jdbc.update("INSERT INTO commerce_retention_order_state(order_id,restore_blocked) VALUES(10,TRUE)");}var r=review();assertThat(r.code()).isEqualTo(Code.QUARANTINED);assertThat(r.sources()).hasSize(7);assertThat(r.totals().stoppedIntents()).isEqualTo(1);assertThat(r.totals().historicalAcknowledgements()).isEqualTo(1);assertThat(r.totals().sourcesWithFreshMatches()).isZero();for(var s:r.sources())assertThat(s.reasons()).contains(Reason.ROOT_QUARANTINED);assertThat(source(r,Participant.PAYMENT).intents().getFirst().progress().inspection()).isEqualTo(Inspection.BLOCKED);}
    @Test void incompletePlanAndCorruptIntentDoNotReturnPartialSuccess(){jdbc.execute("TRUNCATE commerce_retention_hold_source_requests CASCADE");assertThat(review().code()).isEqualTo(Code.INCONSISTENT_HISTORY);}
    @Test void corruptOneSourceFailsWholeReviewWithoutPartialRows(){matched(Participant.PAYMENT);matched(Participant.RETURNS);jdbc.execute("ALTER TABLE commerce_retention_hold_restoration_attempts DISABLE TRIGGER USER");try{jdbc.update("UPDATE commerce_retention_hold_restoration_attempts SET scope_hash=repeat('b',64) WHERE intent_id IN (SELECT intent_id FROM commerce_retention_hold_repair_intents WHERE source='PAYMENT')");}finally{jdbc.execute("ALTER TABLE commerce_retention_hold_restoration_attempts ENABLE TRIGGER USER");}var r=review();assertThat(r.code()).isEqualTo(Code.INCONSISTENT_HISTORY);assertThat(r.sources()).isEmpty();assertThat(r.totals().intents()).isZero();}
    @ParameterizedTest @ValueSource(strings={"STALE","VERSION","MISSING","UNKNOWN"})
    void sourceSpecificReviewReasonsStaySeparate(String change){UUID id=acknowledged(Participant.PAYMENT);if(change.equals("STALE"))put(Participant.PAYMENT,CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,Instant.now().minusSeconds(60));else refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->new SourceHoldInspectionProtocol.Reply(c,change.equals("VERSION")?SourceHoldInspectionProtocol.Code.MATCH:change.equals("UNKNOWN")?SourceHoldInspectionProtocol.Code.UNKNOWN_PURCHASE:SourceHoldInspectionProtocol.Code.MISSING_HOLD,Instant.now(),change.equals("UNKNOWN")?0:change.equals("VERSION")?3:2,change.equals("UNKNOWN")?0:5));var s=source(review(),Participant.PAYMENT);assertThat(s.reasons()).as("Progress metadata for %s: %s",change,s.intents()).contains(change.equals("STALE")?Reason.STALE_INSPECTION:change.equals("VERSION")?Reason.SOURCE_VERSION_CHANGED:Reason.SOURCE_DISCREPANCY);}
    @Test void finalClockRejectsMatchThatExpiresDuringTheLocalReview(){
        UUID id=matched(Participant.PAYMENT);jdbc.execute("ALTER TABLE commerce_retention_hold_probe_results DISABLE TRIGGER USER");try{jdbc.update("UPDATE commerce_retention_hold_probe_results SET observed_at=clock_timestamp()-interval '14 seconds' WHERE code='MATCH_AS_OF_READ'");}finally{jdbc.execute("ALTER TABLE commerce_retention_hold_probe_results ENABLE TRIGGER USER");}var delay=new java.util.concurrent.atomic.AtomicBoolean(true);var delayed=new DelegatingDataSource(ds){@Override public java.sql.Connection getConnection()throws java.sql.SQLException{var actual=ds.getConnection();return (java.sql.Connection)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{java.sql.Connection.class},(proxy,method,args)->{if(method.getName().equals("prepareStatement") && args[0] instanceof String sql && sql.startsWith("SELECT EXISTS(SELECT 1 FROM commerce_retention_hold_requests") && delay.compareAndSet(true,false))Thread.sleep(1300);try{return method.invoke(actual,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}};var r=new CommerceRetentionHoldRestorationReview(delayed,new DataSourceTransactionManager(delayed)).review(10,intake.requestId(),intake.caseReference());assertThat(delay.get()).isFalse();assertThat(r.code()).isEqualTo(Code.REVIEWED);assertThat(source(r,Participant.PAYMENT).intents().getFirst().progress().inspection()).isEqualTo(Inspection.STALE);assertThat(source(r,Participant.PAYMENT).reasons()).contains(Reason.STALE_INSPECTION);
    }
    @Test void reviewOnlyLocksAndReadsWithoutChangingHistory(){matched(Participant.PAYMENT);var attempts=jdbc.queryForList("SELECT * FROM commerce_retention_hold_restoration_attempts");var results=jdbc.queryForList("SELECT * FROM commerce_retention_hold_restoration_results");var probes=jdbc.queryForList("SELECT * FROM commerce_retention_hold_probes");review();review();assertThat(jdbc.queryForList("SELECT * FROM commerce_retention_hold_restoration_attempts")).isEqualTo(attempts);assertThat(jdbc.queryForList("SELECT * FROM commerce_retention_hold_restoration_results")).isEqualTo(results);assertThat(jdbc.queryForList("SELECT * FROM commerce_retention_hold_probes")).isEqualTo(probes);}
    @Test void clockRollbackStillRequiresAnotherInspectionRatherThanWeakeningProductionOrder(){UUID id=matched(Participant.PAYMENT);jdbc.execute("ALTER TABLE commerce_retention_hold_probes DISABLE TRIGGER USER");try{jdbc.update("UPDATE commerce_retention_hold_probes SET created_at=clock_timestamp()-interval '1 minute' WHERE probe_no=2");}finally{jdbc.execute("ALTER TABLE commerce_retention_hold_probes ENABLE TRIGGER USER");}var r=review();assertThat(source(r,Participant.PAYMENT).intents().getFirst().progress().inspection()).isEqualTo(Inspection.OLDER_THAN_REPAIR);assertThat(source(r,Participant.PAYMENT).reasons()).contains(Reason.INSPECTION_REQUIRED);assertThat(r.repairExecutionAllowed()).isFalse();}
    @Test void callerTransactionAndUnlockedPackageSnapshotAreRejected(){matched(Participant.PAYMENT);UUID id=source(review(),Participant.PAYMENT).intents().getFirst().intentId();new TransactionTemplate(manager).executeWithoutResult(tx->assertThatThrownBy(this::review).hasMessage("RETENTION_HOLD_RESTORATION_REVIEW_CALLER_TRANSACTION"));assertThatThrownBy(()->progress().snapshot(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,id)).hasMessage("RESTORATION_PROGRESS_SNAPSHOT_REQUIRES_TRANSACTION");}
    @Test void sqlFailureNeverLooksLikeSevenMissingSources(){var unavailable=org.mockito.Mockito.mock(javax.sql.DataSource.class);try{org.mockito.Mockito.when(unavailable.getConnection()).thenThrow(new java.sql.SQLException("fixture-private"));}catch(java.sql.SQLException impossible){throw new AssertionError(impossible);}var r=new CommerceRetentionHoldRestorationReview(unavailable,new DataSourceTransactionManager(unavailable)).review(10,intake.requestId(),intake.caseReference());assertThat(r.code()).isEqualTo(Code.UNAVAILABLE);assertThat(r.sources()).isEmpty();assertThat(r.toString()).doesNotContain("fixture-private");}
}
